using VtuberBot.Core;namespace VtuberBot.Tests;public sealed class Tests{[Fact]public void ConfigDefaults(){var d=Directory.CreateTempSubdirectory();try{var c=AppConfig.Load(Path.Combine(d.FullName,"missing.toml"));Assert.Equal("VTuber Bot",c.Name);}finally{d.Delete(true);}}[Fact]public void Database(){var d=Directory.CreateTempSubdirectory();try{using var x=new SqliteDatabase(Path.Combine(d.FullName,"a.db"));x.Open();x.InitializeSchema();Assert.NotNull(x.Connection);}finally{d.Delete(true);}}[Fact]public void EventsIsolateFailure(){var m=new EventManager(new L());var r=new List<string>();m.Subscribe("x",_=>{r.Add("bad");throw new();});m.Subscribe("x",_=>r.Add("good"));m.Emit(new("x"));Assert.Equal(["bad","good"],r);}[Fact]public void ResourcesIdempotent(){var m=new ResourceManager(new L());var n=0;m.Register("a",()=>n++);m.CleanupAll();m.CleanupAll();Assert.Equal(1,n);}[Fact]public void Scheduler(){using var s=new TaskScheduler(new L());using var e=new ManualResetEventSlim();s.ScheduleOnce(TimeSpan.FromMilliseconds(20),e.Set);Assert.True(e.Wait(1000));}[Fact]public void Lifecycle(){var d=Directory.CreateTempSubdirectory();try{var p=Path.Combine(d.FullName,"c.toml");File.WriteAllText(p,"[database]\npath='a.db'");var a=new VtuberApplication(p);a.Initialize();Assert.Equal(AppState.Running,a.State);Assert.Equal(1,a.InternalTestEventsProcessed);a.Shutdown();a.Shutdown();Assert.Equal(AppState.Stopped,a.State);}finally{d.Delete(true);}}[Fact]public void Voice(){Assert.Throws<ArgumentException>(()=>new SpeechRequest(" "));Assert.True((int)SpeechPriority.Low<(int)SpeechPriority.Interrupt);}[Fact]public void ProcessMissingCwd(){using var p=new OwnedProcess(new ProcessSpec(["cmd.exe"],"Z:\missing-vtuber-dir"),new L());Assert.Throws<ProcessManagerException>(()=>p.Start());}[Fact]public void ProcessExitCode(){using var p=new OwnedProcess(new ProcessSpec(["cmd.exe","/c","exit","7"]),new L());p.Start();Assert.Equal(7,p.Wait(TimeSpan.FromSeconds(3)));}}sealed class L:ILogger{public void Info(string m,params object?[]a){}public void Warning(string m,params object?[]a){}public void Error(Exception e,string m,params object?[]a){}}